    local: doc({ lines: [['b', 'Sunlight dancing through the blinds', [['G', 0], ['C', 9], ['D', 17], ['Em', 29]], day(9)]], updatedAt: day(9) }),
    remote: doc({ lines: [['b', 'Sunlight spilling across the blinds', [['G', 0], ['C', 9], ['D', 18], ['Em', 29]], day(10)]], updatedAt: day(10) }),
