    base: doc({ lines: [['b', 'Sunlight spilling through', [['C', 11]]]] }),
    local: doc({ lines: [['b', 'Sunlight on through', [], day(9)]], updatedAt: day(9) }),
    remote: doc({ lines: [['b', 'Morning spilling through', [['C', 10]], day(10)]], updatedAt: day(10) }),
